type Action='increase'|'reduce'|'pause'|'keep';
type InlineTarget={project:string;adAccountId:string;objectId:string};
type Props={inlineTarget?:InlineTarget;state:any;project:string;write:(input:any)=>Promise<boolean>;saving:boolean;compact?:boolean;initialSearch?:string;initialTab?:'cards'|'history'|'learning';liveItems?:any[];presentationCards?:any[]};
type Draft={action:Action;percent:string;reason:string};
type Approval={cardId:string;signature:string;action:Action;percent:number|null;reason:string;proposalId:string;proposalVersion:number;proposalSignature:string};
const actions:Record<Action,{label:string;noun:string;icon:any}>={increase:{label:'Aumentar',noun:'Aumento',icon:ArrowUpRight},reduce:{label:'Reduzir',noun:'Redução',icon:ArrowDownRight},pause:{label:'Pausar',noun:'Pausa',icon:Pause},keep:{label:'Manter',noun:'Manter',icon:Eye}};
const actionOrder:Action[]=['increase','reduce','pause','keep'];
const windows=[['7d','7 dias'],['3d','3 dias'],['yesterday','Dia fechado'],['today','Dia parcial']] as const;
const people:Record<string,{name:string;role:string}>={traffic:{name:'Lia',role:'Tráfego'},creative:{name:'Nina',role:'Criativos'},budget:{name:'Theo',role:'Orçamento'},ops:{name:'Cai',role:'Gestão'}};
const array=(value:any):any[]=>Array.isArray(value)?value:[];
const finite=(value:any):value is number=>typeof value==='number'&&Number.isFinite(value);
const number=(value:any)=>finite(value)?value.toLocaleString('pt-BR',{maximumFractionDigits:2}):'N/D';
const ratio=(value:any)=>finite(value)?number(value)+'x':'N/D';
const stamp=(value:any)=>Number.isFinite(decisionTimestamp(value))?new Date(decisionTimestamp(value)).toLocaleString('pt-BR',{timeZone:'America/Boa_Vista',dateStyle:'short',timeStyle:'short'}):'Data N/D';
const time=decisionTimestamp;
function dayLabel(value:any,timezone='America/Boa_Vista') {try{return Number.isFinite(time(value))?new Intl.DateTimeFormat('pt-BR',{timeZone:timezone,day:'2-digit',month:'2-digit'}).format(new Date(value)):'N/D';}catch{return 'N/D';}}
function dayKey(value:any,timezone='America/Boa_Vista') {try{return Number.isFinite(time(value))?new Intl.DateTimeFormat('en-CA',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value)):null;}catch{return null;}}
function windowMeta(card:any,id:string){return {...array(card.sourceCut).find(source=>source.period===id&&source.level==='campaign'),...card.windows?.[id]};}
function windowLabel(card:any,id:string,label:string){const source=windowMeta(card,id),start=dayLabel(source.from,source.timezone),end=dayLabel(Number.isFinite(time(source.to))?new Date(time(source.to)-1).toISOString():null,source.timezone);return start==='N/D'||end==='N/D'?`${label} · análise`:`${label} · ${start===end?start:`${start}–${end}`}`;}
function recentLabel(card:any,prefix:string){const source=windowMeta(card,'3d'),until=dayLabel(Number.isFinite(time(source.to))?new Date(time(source.to)-1).toISOString():null,source.timezone);return `${prefix} · 3d${until==='N/D'?' · análise':` até ${until}`}`;}
function todayDisplay(card:any,now=Date.now()){
 const metrics=card.liveToday||card.windows?.today,source=card.liveToday||windowMeta(card,'today'),value=source.from||source.fetchedAt||card.sourceAt,tz=source.timezone;
 const day=dayKey(value,tz),current=dayKey(new Date(now).toISOString(),tz),label=dayLabel(value,tz);
 return {metrics,label:day&&day===current?'Gasto · hoje':label==='N/D'?'Gasto · análise':`Gasto · ${label}`};
}
function displayedContext(card:any){return Object.prototype.hasOwnProperty.call(card,'displayContext')?card.displayContext:card.context;}
function recommendationSummary(card:any){if(!card.liveDrift)return card.suggestion?.reason||'Conferir aquisição, histórico e últimas edições.';const native=array(card.liveDrift.changes).length>0;if(card.analysisStale)return native?'O status ou o orçamento mudou. A análise anterior precisa ser atualizada.':'A análise anterior precisa ser atualizada para avaliar o cenário de hoje.';return native?'Status ou orçamento mudou. Aguardar nova avaliação antes de decidir.':'As vendas ou o retorno mudaram. Aguardar nova avaliação antes de decidir.';}
const money=(value:any,currency='BRL')=>{if(!finite(value)||!/^[A-Z]{3}$/.test(currency||''))return 'N/D';try{return value.toLocaleString('pt-BR',{style:'currency',currency});}catch{return number(value)+' '+currency;}};
const actionOf=(value:any):Action=>actionOrder.includes(value)?value:'keep';
const statusLabel=(value:any)=>({ACTIVE:'Ativa',PAUSED:'Pausada',CAMPAIGN_PAUSED:'Campanha pausada',WITH_ISSUES:'Com restrição',DELETED:'Excluída'}[String(value)]||String(value||'Status N/D'));
function initialDraft(card:any):Draft {const action=actionOf(card.suggestion?.action);return {action,percent:finite(card.suggestion?.percent)?String(card.suggestion.percent):'20',reason:''};}
function keyOf(card:any){return card.id+':'+card.signature;}
function equivalent(value:any,row:any){return row.budgetCurrency!=='BRL'&&finite(row.budgetRate)&&row.budgetRate>0&&finite(value)?money(Math.round(value*row.budgetRate*100)/100):null;}
function choiceStatus(choice:any,state:any){
 if(!choice)return null;
 if(readChoiceResolution(state,choice))return 'Aplicação conferida';
 const link=array(state.choiceLinks).find(x=>x.choiceId===choice.id),proposal=array(state.proposals).find(x=>x.id===(link?.proposalId||choice.proposalId));
 const execution=array(state.executions).find(x=>x.proposalId===(proposal?.id||choice.proposalId));
 if(readLiveChoiceResolution(state,choice))return 'Aplicação conferida';
 if(execution?.status==='Confirmada')return 'Conferência da aplicação pendente';
 if(execution?.status)return execution.status;
 return choice.status||'Escolha registrada';
}
function ChangePreview({card,draft}:{card:any;draft:Draft}){
 const row=card.row||{},percent=percentage(draft),before=row.dailyBudget,after=nativeAfter(before,draft.action,percent),beforeBRL=equivalent(before,row),afterBRL=equivalent(after,row),old=!!(card.liveDrift||card.analysisStale||card.monitor?.requiresReview);
 if(draft.action==='keep')return <div className="dc-preview dc-preview-keep"><Eye size={20}/><div><strong>Manter a situação atual</strong><p>A escolha fica no aprendizado. Nenhum comando será enviado à Meta.</p></div></div>;
 if(draft.action==='pause')return <div className="dc-preview dc-preview-pause"><span><small>{old?'Status da análise':'Status observado'}</small><strong>{statusLabel(row.status)}</strong></span><ArrowRight size={19}/><span><small>Sua decisão</small><strong>Pausar</strong></span></div>;
 return <div className="dc-preview-wrap"><div className="dc-preview"><span><small>{old?'Diário da análise':'Diário atual'} · {row.budgetCurrency||'moeda N/D'}</small><strong>{money(before,row.budgetCurrency)}</strong>{beforeBRL&&<em>≈ {beforeBRL}</em>}</span><ArrowRight size={19}/><span><small>Diário proposto</small><strong>{validPercent(draft)?money(after,row.budgetCurrency):'—'}</strong>{validPercent(draft)&&afterBRL&&<em>≈ {afterBRL}</em>}</span><b className={'dc-percent dc-'+draft.action}>{draft.action==='increase'?'+':'−'}{percent!==null?number(percent):'—'}%</b></div>{beforeBRL&&<p className="dc-conversion">Equivalência em reais pela cotação da leitura ({number(row.budgetRate)}). A decisão usa os valores exatos em {row.budgetCurrency}.</p>}</div>;
}
function SourceStamps({card}:{card:any}){return <span className="dc-source-stamps"><small>Acompanhamento: {card.liveAt?stamp(card.liveAt):'sem leitura atual'}{card.liveAt&&(card.liveStale||card.liveSourceStale)?' · leitura ou origem desatualizada':''}</small><small>Análise: {stamp(card.sourceAt)}{card.analysisStale||card.liveDrift?' · releitura pendente':''}</small></span>;}
function LiveWindow({card}:{card:any}){
 const live=card.liveToday;if(!live)return null;
 return <section className="dc-live-window" aria-label="Acompanhamento separado da análise"><h4>Acompanhamento · {dayLabel(live.from||live.fetchedAt,live.timezone)}</h4><p>Leitura {stamp(card.liveAt||live.fetchedAt)}{card.liveStale?' · leitura desatualizada':''}. Estes dados de acompanhamento não substituem a análise registrada.</p><dl><div><dt>Gasto</dt><dd>{money(live.spend)}</dd></div><div><dt>Vendas front</dt><dd>{number(live.frontOrders)}</dd></div><div><dt>ROAS</dt><dd>{ratio(live.roas)}</dd></div><div><dt>ROI</dt><dd>{ratio(live.roi)}</dd></div><div><dt>CPA Front</dt><dd>{money(live.cpaFront)}</dd></div><div><dt>Custo / IC</dt><dd>{money(live.ic)}</dd></div></dl></section>;
}
function Windows({card}:{card:any}) {return <><LiveWindow card={card}/><div className="dc-table-scroll"><table className="dc-windows"><caption>Análise registrada em {stamp(card.sourceAt)}. Períodos congelados desta análise; não são o acompanhamento de hoje.</caption><thead><tr><th>Período da análise</th><th>Gasto</th><th>ROAS</th><th>ROI</th><th>Front</th><th>Custo / IC</th></tr></thead><tbody>{windows.map(([id,label])=>{const metrics=card.windows?.[id];return <tr key={id}><th scope="row">{windowLabel(card,id,label)}</th><td>{money(metrics?.spend)}</td><td>{ratio(metrics?.roas)}</td><td>{ratio(metrics?.roi)}</td><td>{number(metrics?.frontOrders)}</td><td>{money(metrics?.ic)}</td></tr>;})}</tbody></table><p className="dc-note">Performance em reais. Janelas sobrepostas não são somadas. Pedidos extras e upsells não são novas vendas front.</p></div></>;}
function TeamOpinions({card,state}:{card:any;state:any}){
 const opinions=array(card.teamOpinions);
 return <div className="dc-opinions">{opinions.length>0&&(!card.teamReady||card.liveDrift)&&<p className="dc-note">Pareceres da análise anterior. Ainda não representam o acompanhamento atual.</p>}{opinions.map((opinion:any,index:number)=>{const person=people[opinion.agentId]||{name:'Agente',role:'Parecer'};return <article key={opinion.id||index}><span className={'dc-person dc-person-'+opinion.agentId}>{person.name.slice(0,1)}</span><div><strong>{person.name}<small>{person.role}</small></strong><AgentReport target={{adAccountId:card.row.adAccountId,externalId:card.row.externalId}} message={array(state.collaborationMessages).find(m=>m.id===opinion.id)||{...opinion,project:card.project,roundId:card.roundId,fromAgent:opinion.agentId,kind:'conclusion'}} state={state}/></div></article>;})}{!opinions.length&&<p className="dc-note">Os novos pareceres individuais desta campanha ainda não estão disponíveis. A equipe precisa reler o cenário atual.</p>}</div>;
}
function DecisionContext({card}:{card:any}){
 const context=displayedContext(card);if(!context)return null;
 return <aside className={'dc-context-review dc-context-'+context.tone} aria-label="Contexto da decisão"><strong><Clock3 size={14}/>{context.title}</strong><p>{context.summary}</p><details><summary>O que conferir antes da ação <ChevronDown size={13}/></summary><p>{context.limitation}</p>{card.postEdit?.available&&<p><strong>Após a edição observada</strong><br/>{money(card.postEdit.spend,card.postEdit.currency)} gastos · {number(card.postEdit.orders)} pedidos · resultado {money(card.postEdit.profit,card.postEdit.currency)}.<br/><small>{stamp(card.postEdit.from)} até {stamp(card.postEdit.to)} · horas encerradas. Pedidos incluem upsells; não são vendas front. Este recorte não prova o efeito do ajuste.</small></p>}{card.postEdit&&!card.postEdit.available&&<p className="dc-note">Pós-ajuste: N/D. {card.postEdit.reason}</p>}<ul>{context.checks.map((check:string)=><li key={check}>{check}</li>)}</ul><p>Lucro passado não protege perdas indefinidamente. Incidente confirmado ou limite autorizado pode exigir contenção, com análise e aprovação exatas.</p></details></aside>;
}
function MonitoringContext({card}:{card:any}){
 const drift=card.liveDrift,monitor=card.monitor;if(!drift&&!monitor)return null;
 const changedDay=drift?.kind==='day'||array(drift?.materialChanges).some(change=>change.field==='todayWindow'),nativeChanged=drift?.kind==='native'||array(drift?.changes).length>0;
 const summary=drift?.kind==='analysis-stale'?'A análise registrada venceu. Aguardar nova leitura dos quatro períodos e novos pareceres antes de decidir.':nativeChanged?'Uma leitura mais nova mostra status ou orçamento diferente. Aguardar releitura antes de repetir uma decisão anterior.':changedDay?'O dia mudou. O acompanhamento atual fica separado das janelas da análise anterior; aguarde a leitura do novo dia.':'As conversões ou o retorno mudaram desde a análise. O acompanhamento foi atualizado; a equipe precisa rever a recomendação com esses novos resultados.';
 return <aside className="dc-context-review dc-context-amber" aria-label="Retomada e releitura"><strong><RefreshCw size={14}/>{drift?.title||monitor.title}</strong><p>{drift?summary:monitor.summary}</p>{nativeChanged&&<p>Orçamento observado: {money(card.observedRow?.dailyBudget,card.observedRow?.budgetCurrency)} / dia. A prévia financeira continua vinculada à análise anterior.</p>}<small>{drift?.kind==='analysis-stale'?`Análise registrada em ${stamp(card.sourceAt)}`:drift?`Leitura recebida em ${stamp(drift.at)}`:`Contexto registrado em ${stamp(monitor.at)}`}{monitor?.ready&&!drift?' · Nova análise disponível.':''}</small></aside>;
}
function ActionBox({card,state,draft,setDraft,saving,now,onSave,onApprove,liveItems=[]}:{card:any;state:any;liveItems?:any[];draft:Draft;setDraft:(draft:Draft)=>void;saving:boolean;now:number;onSave:(card:any,draft:Draft)=>void;onApprove:(card:any,draft:Draft,proposal:any)=>void}){
 const row=card.row||{},observedRow=card.observedRow||row,action=draft.action,proposal=exactProposal(card,draft,now);
 const contingency=decisionContingency({state,project:card.project,row:observedRow,proposal,action,percent:percentage(draft),liveItems,now:Math.max(now,Date.now())});
 const actionable=decisionIntentActions(card),blocked=array(card.blockedReasons),draftError=decisionDraftError(card,draft),valid=!draftError,canRecord=!saving&&!state.paused&&!!card.signature&&actionable[action]===true&&valid,canSave=canRecord&&(!proposal||!contingency.blocked&&card.actionable?.[action]!==false);
 const saved=card.lastChoice,latestStatus=choiceStatus(saved,state);
 function select(next:Action){setDraft({...draft,action:next,percent:next==='reduce'&&Number(draft.percent)>=100?'20':draft.percent||'20'});}
 return <div className="dc-action-box">{!proposal&&<p className="dc-inline-note" role="status">Você pode registrar sua intenção enquanto a equipe relê o cenário. Isso não altera a campanha. Os valores abaixo são referência da análise; a execução exige uma proposta atualizada e sua aprovação exata.</p>}<div className="dc-action-label"><span>1. Escolha a ação</span>{saved&&<span className="dc-recorded"><History size={11}/>{latestStatus}</span>}</div><div className="dc-action-grid" role="group" aria-label={'Ação para '+row.name}>{actionOrder.map(id=>{const ActionIcon=actions[id].icon;return <Button type="button" key={id} aria-pressed={action===id} disabled={saving||state.paused||actionable[id]===false||(id==='pause'&&row.status==='PAUSED')} onClick={()=>select(id)} className={'dc-action dc-'+id+(action===id?' dc-selected':'')}><ActionIcon size={16}/>{actions[id].label}</Button>;})}</div>
   {['increase','reduce'].includes(action)&&<div className="dc-percentage-controls"><div className="dc-presets" role="group" aria-label="Percentuais rápidos">{(action==='increase'?[20,50,100]:[20,30,50]).map(value=><Button type="button" key={value} aria-pressed={Number(draft.percent)===value} onClick={()=>setDraft({...draft,percent:String(value)})} disabled={saving}>{action==='increase'?'+':'−'}{value}%</Button>)}</div><label className="dc-custom-percent"><span>Personalizar</span><span><Input type="number" aria-label={'Percentual para '+row.name} min="0.01" max={action==='increase'?1000:99.99} step="0.01" value={draft.percent} onChange={e=>setDraft({...draft,percent:e.target.value})} disabled={saving}/><b>%</b></span></label></div>}
   {!valid&&<p className="dc-validation" role="alert">{draftError} {action==='reduce'?'Para interromper, escolha Pausar.':''}</p>}
   {observedRow.status==='PAUSED'&&['increase','reduce'].includes(action)&&<p className="dc-inline-note">A última leitura mostra a campanha pausada. Ajustar o diário não autoriza reativação.</p>}
   <ChangePreview card={card} draft={draft}/>
   <label className="dc-reason-input"><span>O que pesou na sua decisão?<small>Opcional · ajuda a equipe a entender seu raciocínio</small></span><Textarea aria-label={'Motivo da decisão para '+row.name} value={draft.reason} maxLength={2500} rows={2} placeholder="Ex.: vendeu front de novo depois do aumento." onChange={e=>setDraft({...draft,reason:e.target.value})} disabled={saving}/></label>
   <p className="dc-selection-hint">2. Confirme abaixo para registrar e retirar este card da fila.</p><div className="dc-submit-row">{proposal?<Button type="button" className="dc-button dc-primary" disabled={!canSave} onClick={()=>onApprove(card,draft,proposal)}><ShieldCheck size={15}/>{action==='pause'?'Aprovar execução · pausar':`Aprovar execução · ${money(nativeAfter(row.dailyBudget,action,percentage(draft)),row.budgetCurrency)}/dia`}</Button>:<Button type="button" className="dc-button dc-primary" disabled={!canSave} onClick={()=>onSave(card,draft)}>{saving?<Loader2 size={15} className="spin"/>:action==='keep'?<Check size={15}/>:<ArrowRight size={15}/>} {action==='keep'?'Registrar decisão e retirar da fila':'Registrar intenção · não executa'}</Button>}{proposal&&<Button type="button" variant="outline" disabled={!canRecord} onClick={()=>onSave(card,draft)}>Registrar só intenção · não executa</Button>}</div>
   <p className="dc-submit-note">{proposal?'A aprovação vale apenas para esta versão e os valores exibidos.':action==='keep'?'Sua escolha é um exemplo de decisão. Resultado financeiro será conferido separadamente.':'A equipe confere o contexto e prepara a proposta exata para sua aprovação. Ainda não executa o ajuste.'}</p>
  </div>;
}
function Card({card,state,draft,setDraft,saving,now,onSave,onApprove,liveItems=[]}:{card:any;state:any;liveItems?:any[];draft:Draft;setDraft:(draft:Draft)=>void;saving:boolean;now:number;onSave:(card:any,draft:Draft)=>void;onApprove:(card:any,draft:Draft,proposal:any)=>void}){
 const row=card.row||{},observedRow=card.observedRow||row,action=draft.action,proposal=exactProposal(card,draft,now),reviewed=decisionSuggestion(card),review=decisionReviewState(card,state,now),recommended=reviewed||card.suggestion||{},origin=!reviewed?'Sem sugestão concluída':recommended.origin==='team'?'Sugestão da equipe':recommended.origin==='proposal'?(card.proposal?.status==='Em revisão'?'Proposta em revisão':'Proposta revisada'):'Triagem · aguarda equipe';
 const blocked=array(card.blockedReasons),Icon=reviewed?actions[actionOf(recommended.action)].icon:Search;
 const today=todayDisplay(card,now);
 return <UiCard className={'dc-card dc-card-'+actionOf(recommended.action)} aria-label={'Decisão para '+row.name}>
  <header className="dc-card-head"><div className="dc-card-tags"><span className="dc-phase">{card.phase||'Fase N/D'}</span><Badge variant="outline" className={'dc-state '+(observedRow.effectiveStatus==='ACTIVE'?'dc-active':'')}>{statusLabel(observedRow.effectiveStatus||observedRow.status)}</Badge></div><h3>{row.name||'Campanha sem nomenclatura'}</h3><div className="dc-card-identity"><strong>{state.config?.[card.project]?.projectName} · {row.accountName||'Conta sem nome'}</strong><code>ID da campanha: {row.externalId||'N/D'}</code></div></header>
  <ActivityChip card={card} state={state} now={now}/><MetricEvolution card={card}/>
  <MonitoringContext card={card}/>
  <CampaignActivityLog card={card} state={state} now={now}/>
  <div className="dc-suggestion"><span className={'dc-suggestion-icon dc-'+actionOf(recommended.action)}><Icon size={21}/></span><div><small>{origin}</small><strong>{!reviewed?review.label:actions[actionOf(recommended.action)].label}{reviewed&&finite(recommended.percent)&&['increase','reduce'].includes(recommended.action)?` ${number(recommended.percent)}%`:''}</strong></div>{reviewed&&<span className="dc-consensus" title="Pareceres da campanha disponíveis"><Check size={12}/> Equipe</span>}</div>
  <details className="dc-rationale"><summary><p className="dc-reason dc-reason-preview">{reviewed?recommendationSummary(card):review.detail}</p><span>Ler análise <ChevronDown size={13}/></span></summary><p className="dc-reason">{recommended.reason||'Conferir os períodos e o efeito dos ajustes anteriores antes da próxima decisão.'}</p></details>
  <div className="dc-card-metrics"><span><small>{recentLabel(card,'ROAS')}</small><strong>{ratio(card.windows?.['3d']?.roas)}</strong></span><span><small>{recentLabel(card,'Front')}</small><strong>{number(card.windows?.['3d']?.frontOrders)}</strong></span><span><small>{today.label}</small><strong>{money(today.metrics?.spend)}</strong></span></div>
  <DecisionContext card={card}/>
  <DecisionContingency state={state} card={card} proposal={proposal} action={action} percent={percentage(draft)} liveItems={liveItems} now={now}/>
  <CampaignDailyResults card={card} state={state} now={now} key={JSON.stringify([card.project,row.adAccountId,row.externalId])} projectId={card.project} adAccountId={row.adAccountId} objectId={row.externalId}/>
  <ActionBox card={card} state={state} draft={draft} setDraft={setDraft} saving={saving} now={now} onSave={onSave} onApprove={onApprove} liveItems={liveItems}/>
  {blocked.length>0&&<details className="dc-detail dc-pending"><summary><Clock3 size={13}/>{blocked.length} {blocked.length===1?'ponto para conferir':'pontos para conferir'}<ChevronDown size={13}/></summary><ul>{blocked.map((text:any,index:number)=><li key={index}>{String(text)}</li>)}</ul></details>}
  <details className="dc-detail"><summary><BookOpen size={14}/> Ver períodos e pareceres<ChevronDown size={14}/></summary><Windows card={card}/><TeamOpinions card={card} state={state}/></details>
  <footer className="dc-card-foot"><SourceStamps card={card}/><details><summary>IDs e origem</summary><dl><dt>Campanha Meta</dt><dd>{row.externalId||'N/D'}</dd><dt>Conta</dt><dd>{row.adAccountId||'N/D'}</dd><dt>Moeda do diário</dt><dd>{row.budgetCurrency||'N/D'}</dd><dt>Rodada</dt><dd>{card.roundId||'Sem rodada conjunta'}</dd></dl></details></footer>
 </UiCard>;
}
